styles:
.b-hero {
    --hero-ring: var(--site-color-accent);
    container-type: inline-size;
    position: relative;
    isolation: isolate;
    overflow: hidden;
    padding-block: var(--site-section-space, var(--site-space-7));
    color: var(--site-color-text);
}

.b-hero--surface,
.b-hero--accent,
.b-hero--image {
    border-radius: var(--site-radius-lg);
}

.b-hero.site-bleed {
    border-radius: 0;
}

.b-hero--surface {
    background: var(--site-color-surface-muted);
}

.b-hero--accent {
    --hero-ring: var(--site-color-accent-contrast);
    background: var(--site-color-accent);
    color: var(--site-color-accent-contrast);
}

/* Over a picture the words are the page's background on a shade of its text: they read on any
   picture, and the night preset turns both round together. */
.b-hero--image {
    --hero-ring: var(--site-color-bg);
    display: flex;
    align-items: flex-end;
    min-height: 22rem;
    background: var(--site-color-text);
    color: var(--site-color-bg);
}

.b-hero__picture {
    position: absolute;
    inset: 0;
    z-index: -2;
    width: 100%;
    max-width: none;
    height: 100%;
    border-radius: 0;
    object-fit: cover;
}

.b-hero__shade {
    position: absolute;
    inset: 0;
    z-index: -1;
    background: linear-gradient(to top, color-mix(in srgb, var(--site-color-text) 85%, transparent), color-mix(in srgb, var(--site-color-text) 45%, transparent));
}

.b-hero__inner {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    /* Between the title and the subtitle; the buttons take the rest of their own space below. */
    gap: var(--site-section-title-space, var(--site-space-4));
    width: 100%;
    max-width: var(--site-container-width);
    margin-inline: auto;
    padding-inline: var(--site-space-5);
}

/* On the page itself the words keep to the column's left edge, like the text under them. */
.b-hero--plain .b-hero__inner {
    padding-inline: 0;
}

.b-hero.site-bleed .b-hero__inner {
    padding-inline: var(--site-section-gutter, var(--site-gutter));
}

.b-hero--center .b-hero__inner {
    align-items: center;
    text-align: center;
}

.b-hero__title {
    max-width: 22em;
    margin: 0;
    color: inherit;
    font-family: var(--site-font-heading);
    font-size: var(--site-font-size-2);
    line-height: 1.1;
    hyphens: auto;
}

.b-hero__subtitle {
    max-width: 40em;
    margin: 0;
    font-size: var(--site-font-size-5);
}

.b-hero--plain .b-hero__subtitle,
.b-hero--surface .b-hero__subtitle {
    color: var(--site-color-text-muted);
}

.b-hero__actions {
    display: flex;
    flex-wrap: wrap;
    gap: var(--site-space-3);
    /* The text → buttons space less the gap that stands there already. */
    margin-top: calc(var(--site-section-actions-space, var(--site-space-4) + var(--site-space-2)) - var(--site-section-title-space, var(--site-space-4)));
}

.b-hero--center .b-hero__actions {
    justify-content: center;
}

.b-hero--accent .b-hero__button:not(.b-hero__button--quiet) {
    background: var(--site-color-accent-contrast);
    color: var(--site-color-accent);
}

.b-hero__button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 44px;
    padding: 0 var(--site-space-5);
    border: 1px solid transparent;
    border-radius: var(--site-radius-md);
    background: var(--site-color-accent);
    color: var(--site-color-accent-contrast);
    font-weight: 600;
    line-height: 1.2;
    text-align: center;
    text-decoration: none;
    transition: background-color var(--site-duration) var(--site-easing), color var(--site-duration) var(--site-easing);
}

.b-hero__button:hover {
    background: color-mix(in srgb, var(--site-color-accent) 85%, var(--site-color-text));
}

.b-hero__button:focus-visible {
    outline: 2px solid var(--hero-ring);
    outline-offset: 2px;
}

.b-hero__button--quiet,
.b-hero__button--quiet:hover {
    border-color: currentColor;
    background: transparent;
    color: inherit;
}

@container (min-width: 40rem) {
    .b-hero {
        padding-block: var(--site-section-space, var(--site-space-8));
    }

    .b-hero__inner {
        padding-inline: var(--site-space-7);
    }

    .b-hero__title {
        font-size: var(--site-font-size-1);
    }

    .b-hero--image {
        min-height: 30rem;
    }
}

/* The accented words of the heading (==words==) cannot take the accent colour on the accent or over a photo: they keep the colour and lean instead. */
.b-hero--accent .site-accent,
.b-hero--image .site-accent {
    color: inherit;
    font-style: italic;
}

/* Sliding over the section above (`overlap`), the edge picture stands over the block's top: the block leaves it uncut, and a frame of its own crops the picture. */
.b-hero[data-webx-overlap] {
    overflow: visible;
}

.b-hero__media {
    position: absolute;
    inset: 0;
    z-index: -1;
    overflow: hidden;
    border-radius: inherit;
}

/* The eyebrow over the H1 (`eyebrow`), styled as every block's: the optional eyebrow tokens of
   THEMES §7.2. The gap of `__inner` stands under it already, so the margin is what is left of the
   eyebrow → heading space. */
.b-hero__eyebrow {
    max-width: 40em;
    margin: 0 0 calc(var(--site-eyebrow-space, var(--site-space-2)) - var(--site-section-title-space, var(--site-space-4)));
    /* Unset, the parent's: font-family and line-height are inherited. */
    font-family: var(--site-eyebrow-font);
    font-size: var(--site-eyebrow-size, var(--site-font-size-6));
    font-weight: var(--site-eyebrow-weight, 600);
    line-height: var(--site-eyebrow-line-height);
    letter-spacing: var(--site-eyebrow-letter-spacing, 0.08em);
    text-transform: var(--site-eyebrow-case, uppercase);
}

/* The badge (`badge`): a picture with transparency — award ribbons, a seal — in the middle under
   the words and the buttons, with no shade over it. Its size and its space are the block's own
   variables, one fluid value each (169×362 → `--hero-badge-height: clamp(…)`); the width only
   keeps it inside the column. */
.b-hero__badge {
    align-self: center;
    width: auto;
    max-width: min(100%, var(--hero-badge-width, 100%));
    height: var(--hero-badge-height, clamp(8rem, 30cqi, 12rem));
    margin-top: calc(var(--hero-badge-space, var(--site-space-7)) - var(--site-section-title-space, var(--site-space-4)));
    border-radius: 0;
    object-fit: contain;
}

/* The first screen (`height: screen`): as tall as the window. Under a header that stands over
   the page (`webx-header--overlay`) the first hero starts under it (the first section of `<main>`:
   breadcrumbs and a hidden notice may stand before it), so it is the whole window and
   its words keep clear of the header (`--hero-under`); under a header in the flow the two of them
   are the window (`--hero-above`). Both are 0 without JavaScript: nothing measures the header
   then, and it does not stand over the page either. A least height: words that need more make
   the block taller. */
.b-hero--screen:first-of-type:where(.site-main > *):where(.site:has(.webx-header--overlay) *) {
    --hero-under: calc(var(--webx-header-height, 0px) + var(--webx-header-topbar-height, 0px));
}

.b-hero--screen:first-of-type:where(.site-main > *):where(.site:not(:has(.webx-header--overlay)) *) {
    --hero-above: calc(var(--webx-header-height, 0px) + var(--webx-header-topbar-height, 0px));
}

.b-hero.b-hero--screen {
    display: flex;
    align-items: center;
    min-height: 100vh;
    min-height: calc(100svh - var(--hero-above, 0px));
    padding-block-start: calc(var(--hero-under, 0px) + var(--site-section-space, var(--site-space-7)));
}

/* At the top (`position: top`), the inner pages' first screen: the words under the header at the
   block's own `--hero-top-space` (119px on 1920 and 64px on 375 → a clamp), the badge under them. */
.b-hero.b-hero--screen.b-hero--at-top {
    align-items: flex-start;
    padding-block-start: calc(var(--hero-under, 0px) + var(--hero-top-space, var(--site-space-8)));
}

@container (min-width: 40rem) {
    .b-hero.b-hero--screen {
        min-height: 100vh;
        min-height: calc(100svh - var(--hero-above, 0px));
        padding-block-start: calc(var(--hero-under, 0px) + var(--site-section-space, var(--site-space-8)));
    }

    .b-hero.b-hero--screen.b-hero--at-top {
        padding-block-start: calc(var(--hero-under, 0px) + var(--hero-top-space, var(--site-space-8)));
    }
}
